393	256      private static BigInteger choose(BigInteger n, BigInteger k) {
394	257          BigInteger nmk = n.subtract(k);
395	258          if (nmk.compareTo(k) < 0) {
396	259              BigInteger t = k;
397	260              k = nmk;
398	261              nmk = t;
399	262          }
400	263          // Will multiply (k) terms, n-k+1 through n-k+k
401	264          // will divide by k terms, 1 through k
402	265          // Note that if we divide after multiplying, it will
403	266          // always be evenly divisible.
404	267          // Proof: when we divide by k, we've multiplied by k consecutive integers,
405	268          // at least one of which will be a multiple of k.
406	269          BigInteger accum = BigInteger.ONE;
407	270          for (BigInteger j = BigInteger.ONE; j.compareTo(k) <= 0; j = j.add(BigInteger.ONE)) {
408	271              nmk = nmk.add(BigInteger.ONE);
409	272              accum = accum.multiply(nmk).divide(j);
410	273          }
411	274          return accum;
