# sitediff.py <base-commit> <landed-sites.tsv> <after-errors.tsv>: the after run's sites with every line number
# in an edited library file mapped back to the base through git diff -U0 (an inserted line -> INS), then the
# two multisets of rows compared; prints the rows only in the landed table (-) and only after (+).
import re, subprocess, sys, collections
base, landed, after = sys.argv[1:4]
files = {'FortressLibrary.fss':'Library/FortressLibrary.fss','FortressLibrary.fsi':'Library/FortressLibrary.fsi',
         'FortressBuiltin.fss':'ProjectFortress/LibraryBuiltin/FortressBuiltin.fss','FortressBuiltin.fsi':'ProjectFortress/LibraryBuiltin/FortressBuiltin.fsi'}
maps = {}
for short, path in files.items():
    d = subprocess.run(['git','diff','-U0',base,'--',path],capture_output=True,text=True,cwd='/home/user/fortress-numlib').stdout
    hunks = []
    for m in re.finditer(r'^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@', d, re.M):
        os_, oc, ns, nc = int(m.group(1)), int(m.group(2) or 1), int(m.group(3)), int(m.group(4) or 1)
        hunks.append((os_, oc, ns, nc))
    maps[short] = hunks
def back(short, n):
    off = 0
    for os_, oc, ns, nc in maps[short]:
        if nc == 0:
            if n > ns: off = (os_ + oc) - (ns + nc) if False else off
        start_new = ns if nc > 0 else ns + 1
        if nc > 0 and ns <= n < ns + nc:
            return 'INS%d' % n
        if n >= start_new + (0 if nc > 0 else 0) and n >= (ns + nc if nc > 0 else ns + 1):
            off = (os_ + oc if oc > 0 else os_ + 1) - (ns + nc if nc > 0 else ns + 1)
    return str(n + off)
pat = re.compile(r'(FortressLibrary\.fs[si]|FortressBuiltin\.fs[si]):(\d+)')
def norm(s):
    return pat.sub(lambda m: m.group(1)+':'+back(m.group(1), int(m.group(2))), s)
def rows(p, remap):
    c = collections.Counter()
    for l in open(p):
        if l.startswith('#') or not l.strip(): continue
        c[norm(l.rstrip('\n')) if remap else l.rstrip('\n')] += 1
    return c
a, b = rows(landed, False), rows(after, True)
for r in sorted((a - b).elements()): print('-', r[:600])
for r in sorted((b - a).elements()): print('+', r[:600])
print('landed %d after %d gone %d new %d' % (sum(a.values()), sum(b.values()), sum((a-b).values()), sum((b-a).values())))
EOF
