#!/usr/bin/env python3
# sitediff.py <base-commit> <landed-sites.tsv> <after-errors.tsv>: the after run's sites with every line number
# in an edited library file mapped back to the base (difflib over the two versions; a line not in the base ->
# NEW<n>), then the two multisets of rows compared; prints rows only in the landed table (-) and only after (+).
import re, subprocess, sys, collections, difflib
base, landed, after = sys.argv[1:4]
H='/home/user/fortress-numlib'
files = {'FortressLibrary.fss':'Library/FortressLibrary.fss','FortressLibrary.fsi':'Library/FortressLibrary.fsi',
         'FortressBuiltin.fss':'ProjectFortress/LibraryBuiltin/FortressBuiltin.fss','FortressBuiltin.fsi':'ProjectFortress/LibraryBuiltin/FortressBuiltin.fsi'}
maps = {}
for short, path in files.items():
    old = subprocess.run(['git','show',base+':'+path],capture_output=True,text=True,cwd=H).stdout.split('\n')
    new = open(H+'/'+path).read().split('\n')
    m = {}
    for tag,i1,i2,j1,j2 in difflib.SequenceMatcher(None, old, new, autojunk=False).get_opcodes():
        if tag == 'equal':
            for k in range(j2-j1): m[j1+k+1] = str(i1+k+1)
    maps[short] = m
pat = re.compile(r'(FortressLibrary\.fs[si]|FortressBuiltin\.fs[si])([:.])(\d+)')
def norm(s):
    return pat.sub(lambda mm: mm.group(1)+mm.group(2)+maps[mm.group(1)].get(int(mm.group(3)), 'NEW'+mm.group(3)), s)
def rows(p, remap):
    c = collections.Counter()
    for l in open(p):
        if l.startswith('#') or not l.strip(): continue
        c[norm(l.rstrip('\n')) if remap else l.rstrip('\n')] += 1
    return c
a, b = rows(landed, False), rows(after, True)
for r in sorted((a - b).elements()): print('-', r[:700])
for r in sorted((b - a).elements()): print('+', r[:700])
print('landed %d after %d gone %d new %d' % (sum(a.values()), sum(b.values()), sum((a-b).values()), sum((b-a).values())))
EOF
